"""Builds data/DATASET_MANIFEST.yaml (brief §13) from the per-dataset manifests."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

import yaml

HEADER = (
    "# Generated by scripts/download_datasets.py from data/manifests/*.json. Do not edit by hand.\n"
    "# One record per downloaded dataset (brief §13). Provenance and licences: DATASETS.md.\n"
)


def build_dataset_manifest(data_root: Path) -> list[dict[str, Any]]:
    records = []
    for path in sorted((data_root / "manifests").glob("*.json")):
        m = json.loads(path.read_text(encoding="utf-8"))
        if "manifest_version" not in m:
            continue  # not a download manifest (e.g. charset.json in Phase 4)
        dates = [f["downloaded_utc"][:10] for f in m["files"].values() if "downloaded_utc" in f]
        records.append(
            {
                "dataset": m["dataset"],
                "version": m["version"],
                "source": m["homepage"],
                "license": m["licence"],
                "download_date": max(dates) if dates else None,
                "samples": m.get("counts", {}),
                "preprocessing": "none (raw download; extraction only)",
                "split": m["role"],
                "manifest": path.relative_to(data_root).as_posix(),
            }
        )
    return records


def write_dataset_manifest(data_root: Path) -> Path:
    out = data_root / "DATASET_MANIFEST.yaml"
    body = yaml.safe_dump(build_dataset_manifest(data_root), sort_keys=False, allow_unicode=True)
    text = HEADER + body
    if not out.exists() or out.read_text(encoding="utf-8") != text:
        out.write_text(text, encoding="utf-8", newline="\n")
    return out
